def mark_backorders(apps, schema_editor):
    """Partially shipped orders whose shipped quantity is fully invoiced become Backordered."""
    SalesOrder = apps.get_model("sales", "SalesOrder")
    for order in SalesOrder.objects.filter(status="partial"):
        lines = list(order.lines.all())
        if lines and all(ln.qty_invoiced >= ln.qty_shipped for ln in lines) and any(ln.qty_shipped > 0 for ln in lines):
            order.status = "backorder"
            order.save(update_fields=["status"])


def unmark_backorders(apps, schema_editor):
    apps.get_model("sales", "SalesOrder").objects.filter(status="backorder").update(status="partial")



